{
  "name": "ProScan III显微镜控制器",
  "name_en": "ProScan III microscope controller",
  "manufacturer": "Prior",
  "description": "这是一台用于显微镜电动附件控制的控制器，可连接并管理滤光轮等模块。根据证据，它可控制最多三个滤光轮并进行位置查询与切换，常用于荧光显微成像中的滤光片选择与多附件协同控制。",
  "description_en": "This is a microscope accessory controller used to operate motorized modules such as filter wheels. Based on the evidence, it can control up to three filter wheels and supports position query and switching, making it useful for fluorescence microscopy and coordinated control of microscope peripherals.",
  "tag_hints": [
    "microscope control",
    "filter wheel control",
    "fluorescence microscopy",
    "motorized filter selection",
    "multi-accessory controller"
  ],
  "actions": [
    {
      "action_name": "auto-command",
      "description": "向控制器发送原始命令。",
      "description_en": "Send a raw command to the controller."
    },
    {
      "action_name": "auto-readline",
      "description": "读取控制器返回的一行数据。",
      "description_en": "Read one line of response from the controller."
    },
    {
      "action_name": "auto-read_until_timeout",
      "description": "持续读取返回数据直到通信超时。",
      "description_en": "Read returned data until the communication times out."
    },
    {
      "action_name": "auto-get_command",
      "description": "发送查询命令并返回控制器的应答。",
      "description_en": "Send a query command and return the controller response."
    },
    {
      "action_name": "auto-move_command",
      "description": "发送运动相关命令并等待移动完成响应。",
      "description_en": "Send a motion-related command and wait for the move-complete response."
    },
    {
      "action_name": "auto-set_command",
      "description": "发送设置类命令并检查控制器返回状态。",
      "description_en": "Send a setting command and check the controller return status."
    },
    {
      "action_name": "auto-get_description",
      "description": "查询设备或命令的描述信息。",
      "description_en": "Query descriptive information about the device or a command."
    },
    {
      "action_name": "auto-changed_timeout",
      "description": "临时更改与控制器通信的超时时间。",
      "description_en": "Temporarily change the communication timeout with the controller."
    },
    {
      "action_name": "auto-assert_filterwheel_number",
      "description": "检查指定滤光轮编号是否在有效范围内。",
      "description_en": "Check whether the specified filter wheel number is within the valid range."
    },
    {
      "action_name": "auto-has_filterwheel",
      "description": "检查指定接口是否连接了滤光轮。",
      "description_en": "Check whether a filter wheel is connected on the specified interface."
    },
    {
      "action_name": "auto-get_n_filter_positions",
      "description": "获取指定滤光轮的总工位数。",
      "description_en": "Get the total number of positions on the specified filter wheel."
    },
    {
      "action_name": "auto-get_filter_position",
      "description": "获取指定滤光轮的当前位置。",
      "description_en": "Get the current position of the specified filter wheel."
    },
    {
      "action_name": "auto-set_filter_position",
      "description": "设置指定滤光轮的位置。",
      "description_en": "Set the position of the specified filter wheel."
    }
  ]
}

